sp_widget.client_script:
api.controller = function($scope, $window, $location, $rootScope) {

  /*
   * =========================================================
   * SIDEBAR COLLAPSE / EXPAND
   * =========================================================
   */

  var STORAGE_KEY = 'gatenow_sidebar_collapsed';

  // Restore saved sidebar state
  $scope.isCollapsed =
    $window.localStorage.getItem(STORAGE_KEY) === 'true';


  $scope.toggleSidebar = function() {

    // Toggle state
    $scope.isCollapsed = !$scope.isCollapsed;

    // Persist state
    $window.localStorage.setItem(
      STORAGE_KEY,
      String($scope.isCollapsed)
    );

    // Notify other widgets if needed
    $rootScope.$broadcast(
      'sidebar.toggled',
      $scope.isCollapsed
    );

  };


  /*
   * =========================================================
   * CURRENT PAGE
   * =========================================================
   */

  function getCurrentPageId() {

    var idFromLocation =
      $location.search().id;

    if (idFromLocation) {
      return idFromLocation;
    }

    try {

      return new URLSearchParams(
        $window.location.search
      ).get('id');

    } catch (e) {

      return null;

    }

  }


  $scope.currentId = getCurrentPageId();


  /*
   * =========================================================
   * LOCATION CHANGE
   * =========================================================
   */

  $rootScope.$on(
    '$locationChangeSuccess',
    function() {

      $scope.currentId =
        getCurrentPageId();

    }
  );


  /*
   * =========================================================
   * ACTIVE NAVIGATION ITEM
   * =========================================================
   */

  $scope.isActive = function(pageId) {

    return $scope.currentId === pageId;

  };


  /*
   * =========================================================
   * RIGHT PANEL
   * =========================================================
   */

  var RIGHT_PANEL_KEY =
    'gatenow_right_panel_open';

  $scope.rightPanelOpen =
    $window.localStorage.getItem(
      RIGHT_PANEL_KEY
    ) === 'true';


  /*
   * =========================================================
   * NAVIGATION
   * =========================================================
   */

  $scope.navigate = function(pageId) {

    if (!pageId) {
      return;
    }

    /*
     * Navigate to page
     */
    $location.search('id', pageId);


    /*
     * Reimbursement panel
     */
    if (pageId === 'reimbursement') {

      $scope.rightPanelOpen =
        !$scope.rightPanelOpen;


      $window.localStorage.setItem(
        RIGHT_PANEL_KEY,
        String($scope.rightPanelOpen)
      );


      $rootScope.$broadcast(
        'reimbursementPanel.toggled',
        $scope.rightPanelOpen
      );

    }

  };

};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap');


/* =========================================================
   SIDEBAR WRAPPER
   ========================================================= */

.gatenow-sidebar-wrapper {
  display: flex !important;
  flex: 0 0 auto !important;
  width: auto !important;
  min-width: 0 !important;
  height: 100vh !important;
  position: relative !important;
  z-index: 9999 !important;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.glass-sidebar {
  width: 120px !important;
  min-width: 120px !important;
  max-width: 120px !important;

  flex: 0 0 120px !important;

  height: 100vh !important;

  position: sticky !important;
  top: 0 !important;

  box-sizing: border-box !important;

  font-family: 'Inter', sans-serif;

  z-index: 9999 !important;

  overflow: visible !important;

  background: rgba(255, 255, 255, 0.35);

  backdrop-filter: blur(30px) saturate(220%);
  -webkit-backdrop-filter: blur(30px) saturate(220%);

  border-right: 1px solid rgba(255, 255, 255, 0.6);

  box-shadow:
    inset 1px 0 0 rgba(255, 255, 255, 0.5),
    6px 0 40px rgba(79, 70, 229, 0.15);

  transition:
    width 0.3s cubic-bezier(0.4, 0, 0.2, 1),
    min-width 0.3s cubic-bezier(0.4, 0, 0.2, 1),
    max-width 0.3s cubic-bezier(0.4, 0, 0.2, 1),
    flex-basis 0.3s cubic-bezier(0.4, 0, 0.2, 1);

}


/* =========================================================
   COLLAPSED STATE
   ========================================================= */

.glass-sidebar.is-closed {

  width: 64px !important;
  min-width: 64px !important;
  max-width: 64px !important;

  flex: 0 0 64px !important;

}

/* =========================================================
   HIDE NAV ICONS WHEN COLLAPSED
   ========================================================= */

.glass-sidebar.is-closed .glass-nav {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.2s ease, visibility 0.2s ease;
}

/* =========================================================
   TOGGLE WRAPPER
   ========================================================= */

.sidebar-toggle-wrap {
  width: 100%;
  display: flex;
  justify-content: center;
  position: absolute;
  /* Increased from 24px to push the button down below the global navbar */
  top: 90px; 
  left: 0;
  z-index: 10;
}


/* =========================================================
   TOGGLE BUTTON
   ========================================================= */

.sidebar-toggle {
  position: relative;
  width: 40px;
  height: 40px;
  border: 1px solid transparent;
  background: #f1f5f9;
  color: #0f172a;
  cursor: pointer;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  outline: none;
  line-height: 0;          /* NEW — kills inline baseline gap */
  box-sizing: border-box;  /* NEW — keeps 40x40 exact regardless of border */
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease;
}


.sidebar-toggle:hover {

  background: #e2e8f0;

  border-color: #cbd5e1;

}


.sidebar-toggle:focus {

  outline: none;

}


.sidebar-toggle svg {
  width: 20px;
  height: 20px;
  color: #1e293b;
  display: block;   /* NEW — SVGs default to inline, this removes the offset */
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}


.sidebar-toggle.is-collapsed svg {

  transform: rotate(180deg);

}

/* =========================================================
   TOGGLE WRAPPER
   ========================================================= */

.sidebar-toggle-wrap {
  width: 100%;
  height: 64px;              /* NEW — gives the wrap real hoverable height */
  display: flex;
  justify-content: center;
  align-items: center;
  position: absolute;
  top: 24px;
  left: 0;
  z-index: 10000;
  cursor: pointer;           /* NEW — shows intent across the whole area */
}

/* NEW — hovering anywhere in the wrap triggers the button's hover look */
.sidebar-toggle-wrap:hover .sidebar-toggle {
  background: #e2e8f0;
  border-color: #cbd5e1;
}

.sidebar-toggle-wrap:hover .toggle-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateY(-50%) translateX(15px);
}


/* =========================================================
   TOGGLE TOOLTIP
   ========================================================= */

.toggle-tooltip {

  position: absolute;

  left: 100%;

  top: 50%;

  transform:
    translateY(-50%)
    translateX(5px);

  background: #000000;

  color: #ffffff;

  padding: 8px 14px;

  border-radius: 20px;

  font-size: 13px;

  font-weight: 500;

  white-space: nowrap;

  opacity: 0;

  visibility: hidden;

  transition:
    opacity 0.25s ease,
    visibility 0.25s ease,
    transform 0.25s ease;

  pointer-events: none;

  z-index: 999999 !important;

}


.sidebar-toggle:hover .toggle-tooltip {

  opacity: 1;

  visibility: visible;

  transform:
    translateY(-50%)
    translateX(15px);

}


/* =========================================================
   NAVIGATION
   ========================================================= */

.glass-nav {

  list-style: none !important;

  padding: 0 !important;

  margin: 0 !important;

  display: flex !important;

  flex-direction: column !important;

  gap: 24px !important;

  align-items: center !important;

  width: 100% !important;

  position: absolute !important;

  top: 50% !important;

  left: 0 !important;

  transform: translateY(-50%) !important;

  z-index: 1;

}


.glass-nav li {

  width: 100% !important;

  display: flex !important;

  justify-content: center !important;

  align-items: center !important;

  list-style: none !important;

  margin: 0 !important;

  padding: 0 !important;

  position: relative !important;

}


.glass-nav li a {

  display: flex !important;

  align-items: center !important;

  justify-content: center !important;

  text-decoration: none !important;

  width: 100% !important;

  cursor: pointer;

}


/* =========================================================
   ICON CIRCLE
   ========================================================= */

.icon-circle {

  position: relative;

  width: 56px;

  height: 56px;

  min-width: 56px;

  min-height: 56px;

  border-radius: 50%;

  display: flex;

  align-items: center;

  justify-content: center;

  background: rgba(255, 255, 255, 0.65) !important;

  color: #1e293b !important;

  border: 1px solid rgba(255, 255, 255, 0.7);

  box-shadow:
    0 4px 12px rgba(31, 38, 135, 0.08);

  transition:
    transform 0.25s ease,
    background 0.25s ease,
    box-shadow 0.25s ease;

  flex-shrink: 0;

}


.icon-circle svg,
.icon-circle i {

  width: 20px;

  height: 20px;

  font-size: 20px;

  display: flex;

  align-items: center;

  justify-content: center;

  color: #1e293b !important;

  stroke: #1e293b !important;

}


.icon-circle svg[fill="currentColor"] {

  fill: #1e293b !important;

}


/* =========================================================
   HOVER
   ========================================================= */

.glass-nav li a:hover .icon-circle {

  background: #1765dc !important;

  color: #ffffff !important;

  border-color: transparent !important;

  box-shadow:
    0 8px 24px rgba(23, 101, 220, 0.4);

  transform: scale(1.08);

}


.glass-nav li a:hover .icon-circle i {

  color: #ffffff !important;

}


.glass-nav li a:hover .icon-circle svg {

  stroke: #ffffff !important;

}


.glass-nav li a:hover
.icon-circle svg[fill="currentColor"] {

  fill: #ffffff !important;

}


/* =========================================================
   ACTIVE
   ========================================================= */

.glass-nav li.active .icon-circle {

  background: rgba(255, 255, 255, 0.95) !important;

  color: #1e293b !important;

  border:
    1px solid rgba(255, 255, 255, 0.9) !important;

  box-shadow:
    0 4px 16px rgba(31, 38, 135, 0.12);

  transform: scale(1);

}


.glass-nav li.active .icon-circle i {

  color: #1e293b !important;

}


.glass-nav li.active .icon-circle svg {

  stroke: #1e293b !important;

}


.glass-nav li.active
.icon-circle svg[fill="currentColor"] {

  fill: #1e293b !important;

}


/* =========================================================
   NAVIGATION TOOLTIP
   ========================================================= */

.tooltip-title {

  position: absolute;

  left: 100%;

  top: 50%;

  transform:
    translateY(-50%)
    translateX(-10px);

  opacity: 0;

  visibility: hidden;

  background: rgba(255, 255, 255, 0.85);

  backdrop-filter: blur(12px);

  -webkit-backdrop-filter: blur(12px);

  color: #1e293b;

  padding: 8px 16px;

  border-radius: 8px;

  font-size: 14px;

  font-weight: 600;

  white-space: nowrap;

  box-shadow:
    0 4px 15px rgba(31, 38, 135, 0.15);

  border:
    1px solid rgba(255, 255, 255, 0.6);

  pointer-events: none;

  transition:
    opacity 0.35s ease,
    visibility 0.35s ease,
    transform 0.35s ease;

  z-index: 999999 !important;

}


.tooltip-title::before {

  content: '';

  position: absolute;

  top: 50%;

  right: 100%;

  transform: translateY(-50%);

  border-width: 6px;

  border-style: solid;

  border-color:
    transparent
    rgba(255, 255, 255, 0.85)
    transparent
    transparent;

}


.glass-nav li a:hover .tooltip-title {

  opacity: 1;

  visibility: visible;

  transform:
    translateY(-50%)
    translateX(15px);

}
